'use strict';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state,loadError=false;
try{const raw=window.Android?Android.load():localStorage.getItem('sabz-v1');state=raw?Core.validate(JSON.parse(raw)):null}catch(e){loadError=true}
state = state || {version:1,settings:{...Core.defaults},days:{},custom:[]};
let date=Core.dayKey(new Date()),page='home',cat=null,search='',draft=null,editId=null,calendarAnchor=date,calendarCallback=null,reportStart=Core.shift(date,-6),reportEnd=date,quantityFood=null,quantity=100;
const t=(fa,en)=>state.settings.lang==='fa'?fa:en;
const n=(v,d=0)=>Number(v).toLocaleString(state.settings.lang==='fa'?'fa-IR':'en-US',{maximumFractionDigits:d});
const name=f=>state.settings.lang==='fa'?f.fa:f.en;
const allFoods=()=>[...FOODS,...state.custom];
const today=()=>Core.dayKey(new Date());
const df=(key,opts={})=>new Intl.DateTimeFormat(state.settings.lang==='fa'?'fa-IR':'en-US',{calendar:state.settings.calendar,year:'numeric',month:'long',day:'numeric',...opts}).format(Core.parseDate(key));
const uid=()=>Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,9);
function save(){try{Core.validate(state);const raw=JSON.stringify(state);if(window.Android){if(!Android.save(raw))throw Error('Storage')}else localStorage.setItem('sabz-v1',raw);return true}catch(e){toast(t('ذخیره نشد؛ فضای خالی گوشی و داده‌ها را بررسی کنید.','Could not save. Check storage space and data.'));return false}}
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
function upgradeArt(){document.querySelectorAll('.emoji,.big-emoji').forEach(el=>{const src=ART[el.textContent.trim()];if(src)el.innerHTML='<img src="'+src+'" alt="" aria-hidden="true">'})}
function closeModal(){$('#modal').innerHTML='';calendarCallback=null}
function modal(title,html){$('#modal').innerHTML=`<div class="sheet-back"><section class="sheet" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="sheet-top"><h2>${esc(title)}</h2><button class="iconbtn" data-action="close" aria-label="${t('بستن','Close')}">×</button></div>${html}</section></div>`;upgradeArt()}
function icon(id){const p={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',add:'M12 5v14M5 12h14',calendar:'M5 5h14a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7a2 2 0 0 1 2-2ZM7 3v4m10-4v4M3 10h18',trend:'M5 20v-6m7 6V4m7 16V9',settings:'M4 7h5m6 0h5M4 17h10m5 0h1M9 4v6h6V4ZM14 14v6h5v-6Z'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${p[id]||p.home}"/></svg>`}
function nav(){return `<nav class="nav" aria-label="${t('منوی اصلی','Main navigation')}">${[['home','خانه','Home','home'],['quick','ثبت','Log','add'],['history','تقویم','Calendar','calendar'],['trend','روند','Progress','trend']].map(([p,fa,en,ic])=>`<button data-action="nav" data-page="${p}" class="${page===p?'active':''}">${icon(ic)}<span>${t(fa,en)}</span></button>`).join('')}</nav>`}
function getDay(){return state.days[date]||{entries:[],targets:Core.targets(state.settings),complete:false}}
function ensureDay(){return state.days[date] = state.days[date] || {entries:[],targets:Core.targets(state.settings),complete:false}}
function dateChip(){return `<button class="chip" data-action="date">▦ ${esc(df(date))} ▾</button>`}
function metric(label,value,target,color,unit){const ratio=value/target;return `<div class="metric"><div class="row between progress-label"><strong>${label}</strong><span>${n(value,1)} <small>/ ${n(target)} ${unit}</small></span></div><div class="track"><div class="fill" style="width:${Math.min(100,ratio*100)}%;background:${color}"></div></div><small>${ratio<.9?t(`${n(target-value,1)} ${unit} تا هدف`,`${n(target-value,1)} ${unit} to target`):ratio<=1.1?t('نزدیک هدف','Near target'):t(`${n(value-target,1)} ${unit} بیشتر از هدف`,`${n(value-target,1)} ${unit} above target`)}</small></div>`}
function dashboard(){const d=getDay(),v=Core.totals(d),w=Core.week(state,date);return `${header(t('امروزِ من','My day'))}<div class="row between" style="margin-bottom:16px">${dateChip()}${date!==today()?`<button class="link" data-action="today">${t('بازگشت به امروز','Today')}</button>`:''}</div>${!state.settings.confirmed?`<div class="hint warning" style="margin-bottom:16px">${t('برای شروع، هدف‌های روزانه را بررسی و تأیید کن.','Review and confirm your daily goals to get started.')} <button class="link" data-action="settings">${t('تنظیم هدف‌ها','Set goals')} ←</button></div>`:''}<section class="card hero"><div class="copy"><div class="eyebrow">${t('همراهی در ۷ روز گذشته','YOUR LAST 7 DAYS')}</div><div class="percent">${w.value===null?'—':n(w.value)+'٪'}</div><strong>${w.value===null?t('قدم اول، یک ثبت ساده','Start with one small entry'):w.value>=65?t('عادت‌های کوچک، حال بهتر','Small habits, better days'):t('قدم بعدی را با هم برداریم','One small step together')}</strong><p class="fine">${t(`${n(w.count)} روز کامل از ۷ روز`,`${w.count} complete days out of 7`)}</p></div>${mascot(w.value)}</section><section class="card"><div class="row between" style="margin-bottom:15px"><h3>${t('تغذیهٔ روز','Daily nutrition')}</h3><span class="badge">${t('مقادیر تقریبی','Estimated')}</span></div>${metric(t('کالری','Calories'),v.kcal,d.targets.kcal,'#ed9461','kcal')}${metric(t('پروتئین','Protein'),v.protein,d.targets.protein,'#158b81',t('گرم','g'))}${metric(t('فیبر','Fiber'),v.fiber,d.targets.fiber,'#83b45f',t('گرم','g'))}${v.unknown?`<p class="hint warning">${t('برخی ارزش‌های غذایی نامشخص‌اند؛ جمع‌ها ناقص هستند.','Some nutrient values are unknown; totals are incomplete.')}</p>`:''}</section>${waterCard(v.water,d.targets.water)}<div class="grid2"><div class="card"><span style="font-size:30px">🪑</span><h3>${t('نشستن','Sitting')}</h3><b>${duration(v.sitting)}</b><p class="muted">${t('طولانی‌ترین نوبت','Longest stretch')}: ${duration(v.longest)}</p></div><div class="card"><span style="font-size:30px">👟</span><h3>${t('تحرک','Activity')}</h3><b>${n(v.activity)} ${t('دقیقه','min')}</b><p class="muted">${t('وقفه‌ها','Breaks')}: ${n(v.breaks)}</p></div></div><button class="primary" data-action="nav" data-page="quick">＋ ${t('ثبت سریع','Quick check-in')}</button><div class="actions"><button class="secondary grow" data-action="details">${t('جزئیات و ویرایش روز','Day details & edits')}</button><button class="secondary" data-action="report">PDF ↗</button></div><p class="fine muted" style="margin-top:14px">${t('امتیاز، میزان پیگیری عادت‌هاست؛ تشخیص پزشکی نیست.','The score tracks habits; it is not a medical assessment.')}</p>`}
function newDraft(){return {activities:{},id:uid(),time:new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}),items:[],noFood:false,noDrink:false,sitting:null,longest:null,breaks:null,activity:null,activityType:'walk'}}
function details(){const d=getDay(),v=Core.totals(d),s=Core.score(d);return `${header(t('جزئیات روز','Day details'))}${dateChip()}<div class="card" style="margin-top:18px"><div class="row between"><h2>${t('جمع روزانه','Daily totals')}</h2><span class="chip">${d.complete?t('روز کامل','Complete day'):t('در حال ثبت','In progress')}</span></div>${metric(t('کالری','Calories'),v.kcal,d.targets.kcal,'#e89565','kcal')}${metric(t('پروتئین','Protein'),v.protein,d.targets.protein,'#168d83','g')}${metric(t('فیبر','Fiber'),v.fiber,d.targets.fiber,'#80b55b','g')}<p>${t('آب ساده','Plain water')}: ${n(v.water)} ml</p><p>${t('کگل','Kegel')}: ${n(v.kegel)} / ${n(3)} ${t('نوبت در روز','sessions per day')} ${v.kegel>=3?'✓':''}</p><p>${t('همه نوشیدنی‌ها','All drinks')}: ${n(v.fluids)} ml</p><p>${t('فعالیت / نشستن','Activity / sitting')}: ${n(v.activity)} / ${duration(v.sitting)}</p><p>${t('طولانی‌ترین نشستن','Longest sitting')}: ${duration(v.longest)} · ${t('وقفه‌ها','Breaks')}: ${n(v.breaks)}</p>${v.unknown?`<p class="hint warning">${t('جمع غذایی ناقص است؛ دادهٔ نامشخص وجود دارد.','Nutrient totals are incomplete; some data is unknown.')}</p>`:''}<p class="fine muted">${t('هدف‌ها مربوط به زمان اولین ثبت این روز هستند.','Goals are preserved from the first entry on this day.')}</p></div><section class="card"><h2>${t('ثبت‌های روز','Check-ins')}</h2>${d.entries.map(e=>`<div class="entry"><div class="row between"><strong><bdi dir="ltr">${esc(intervalLabel(e))}</bdi></strong><div><button class="link" data-action="edit-entry" data-id="${esc(e.id)}">${t('ویرایش','Edit')}</button><button class="link" data-action="delete-entry" data-id="${esc(e.id)}">${t('حذف','Delete')}</button></div></div>${e.items.map(i=>`<p>${esc(i.food.emoji)} ${esc(name(i.food))} · ${n(i.amount)} ${i.food.drink?'ml':'g'}</p>`).join('')}${e.noFood?`<p class="muted">${t('چیزی نخوردم','No food')}</p>`:''}${e.noDrink?`<p class="muted">${t('چیزی ننوشیدم','No drinks')}</p>`:''}<p class="muted">🪑 ${e.sitting===null?'—':duration(e.sitting)} · 👟 ${e.activity===null?'—':n(e.activity)} ${t('دقیقه','min')}</p>${e.kegel!==undefined?`<p class="fine muted">${t('کگل','Kegel')}: ${n(e.kegel)} ${t('نوبت','sessions')}</p>`:''}${Object.entries(e.activities||{}).map(([id,m])=>`<p class="fine muted">${name(ACTIVITIES.find(a=>a.id===id)||{fa:'سایر',en:'Other'})}: ${n(m)} ${t('دقیقه','min')}</p>`).join('')}</div>`).join('')||`<div class="empty"><div class="emoji">🍏</div>${t('هنوز چیزی ثبت نشده','Nothing recorded yet')}</div>`}</section><button class="primary" data-action="nav" data-page="quick">＋ ${t('ثبت اطلاعات','Log data')}</button><div class="actions"><button class="secondary grow" data-action="complete">${d.complete?t('باز کردن روز برای ثبت','Reopen day'):t('همهٔ اطلاعات روز را ثبت کرده‌ام','I have recorded the whole day')}</button><button class="secondary" data-action="report">PDF ↗</button></div>${s?`<p class="hint" style="margin-top:12px">${t('امتیاز روز','Day score')}: ${n(s.value)}٪</p>`:''}`}
function calParts(key){return Object.fromEntries(new Intl.DateTimeFormat('en-US-u-nu-latn',{calendar:state.settings.calendar,year:'numeric',month:'numeric',day:'numeric'}).formatToParts(Core.parseDate(key)).filter(p=>p.type!=='literal').map(p=>[p.type,Number(p.value)]))}
function monthStart(key){let d=key;for(let i=0;i<32&&calParts(d).day!==1;i++)d=Core.shift(d,-1);return d}
function calGrid(){let start=monthStart(calendarAnchor),parts=calParts(start),first=Core.parseDate(start).getDay(),offset=state.settings.calendar==='persian'?(first+1)%7:first,days=[];for(let d=start,i=0;i<32;i++,d=Core.shift(d,1)){if(calParts(d).month!==parts.month)break;days.push(d)}const weekdays=state.settings.calendar==='persian'?[t('ش','Sa'),t('ی','Su'),t('د','Mo'),t('س','Tu'),t('چ','We'),t('پ','Th'),t('ج','Fr')]:[t('ی','Su'),t('د','Mo'),t('س','Tu'),t('چ','We'),t('پ','Th'),t('ج','Fr'),t('ش','Sa')];return `<div class="row between" style="margin-bottom:12px"><button class="iconbtn" data-action="month-prev" aria-label="${t('ماه قبل','Previous month')}">‹</button><button class="link" data-action="jump-month">${esc(df(start,{day:undefined}))} ▾</button><button class="iconbtn" data-action="month-next" aria-label="${t('ماه بعد','Next month')}">›</button></div><div class="calendar ${state.settings.calendar==='persian'?'persian':''}">${weekdays.map(x=>`<div class="weekday">${x}</div>`).join('')}${'<span></span>'.repeat(offset)}${days.map(d=>`<button data-action="select-date" data-date="${d}" ${d>today()?'disabled':''} class="${d===date?'selected ':''}${d===today()?'today ':''}${state.days[d]?.entries.length?'dot':''}">${n(calParts(d).day)}</button>`).join('')}</div>`}
function history(){return `${header(t('تقویم و سابقه','Calendar & history'))}<p class="muted" style="margin-bottom:15px">${t('یک روز را برای مشاهده و ویرایش انتخاب کن.','Choose a day to view or edit.')}</p><section class="card" id="calendar-container">${calGrid()}</section><button class="secondary" data-action="today">${t('امروز','Today')}</button><section class="card" style="margin-top:18px"><h2>${t('روزهای ثبت‌شده','Recorded days')}</h2>${Object.keys(state.days).filter(k=>state.days[k].entries.length).sort().reverse().slice(0,60).map(k=>`<button class="row between" style="width:100%;border-bottom:1px solid var(--line)" data-action="open-day" data-date="${k}"><span>${df(k)}</span><span class="muted">${n(Core.totals(state.days[k]).kcal)} kcal ←</span></button>`).join('')||`<p class="muted">${t('پس از اولین ثبت، سابقه اینجا نمایش داده می‌شود.','Your first entry will appear here.')}</p>`}</section>`}
function trend(){const w=Core.week(state,date);return `${header(t('روند من','My progress'))}${dateChip()}<section class="card hero" style="margin-top:16px"><div class="copy"><div class="eyebrow">${t('امتیاز عادت‌های هفت‌روزه','7-DAY HABIT SCORE')}</div><div class="percent">${w.value===null?'—':n(w.value)+'٪'}</div><p>${t(`${n(w.count)} روز کامل از ۷ روز`,`${w.count} complete days out of 7`)}</p></div>${mascot(w.value)}</section><section class="card"><h2>${t('یک قدم در هر روز','One day at a time')}</h2><div class="bars">${w.days.map(d=>`<button class="bar-col" data-action="open-day" data-date="${d.key}"><small>${d.score?n(d.score.value):'—'}</small><div class="bar" style="height:${d.score?Math.max(3,d.score.value*.85):3}px;background:${d.score?'#93c5a7':'#e5e9e3'}"></div><small>${n(calParts(d.key).day)}</small></button>`).join('')}</div></section><section class="card"><h2>${t('امتیاز چطور محاسبه می‌شود؟','How is the score calculated?')}</h2><p class="fine">${t('فقط روزهایی که کامل اعلام کرده‌ای و ارزش غذایی نامشخص ندارند حساب می‌شوند. میانگین امتیاز این روزها در بازهٔ ۷ روزه نمایش داده می‌شود؛ روزهای خالی صفر نیستند.','Only days marked complete with known nutrition count. The display is the average of those days within the 7-day window; missing days are not zero.')}</p><hr class="divider">${[[25,'فیبر','Fiber'],[20,'آب ساده','Plain water'],[15,'پروتئین','Protein'],[15,'تعادل کالری','Calorie balance'],[15,'دقایق فعالیت','Activity minutes'],[10,'وقفه در نشستن','Sitting breaks']].map(([v,fa,en])=>`<div class="row between"><span>${t(fa,en)}</span><b>${n(v)}٪</b></div>`).join('')}<p class="fine muted" style="margin-top:12px">${t('فیبر، پروتئین، آب و فعالیت تا رسیدن به هدف امتیاز می‌گیرند؛ بیشتر خوردن امتیاز اضافه ندارد. امتیاز کالری با فاصله از هدف کم می‌شود. امتیاز نشستن بر اساس نسبت حد پیوستهٔ انتخابی به طولانی‌ترین نوبت است. این فرمول طراحی برنامه است و اعتبار بالینی ندارد.','Fiber, protein, water and activity earn points up to their targets; exceeding them adds no points. Calorie points decrease with distance from the target. Sitting points use your chosen interval limit relative to your longest stretch. This app-designed formula is not clinically validated.')}</p></section><button class="primary" data-action="report">${t('گزارش و خروجی PDF','Reports & PDF export')}</button>`}
const SOURCES=[['NIDDK · Fiber & fluids','https://www.niddk.nih.gov/health-information/digestive-diseases/constipation/eating-diet-nutrition'],['FDA · Calorie reference','https://www.fda.gov/food/nutrition-facts-label/calories-nutrition-facts-label'],['National Academies · Protein DRI','https://www.ncbi.nlm.nih.gov/books/NBK235261/'],['WHO · Physical activity','https://www.who.int/news-room/fact-sheets/detail/physical-activity'],['USDA · FoodData Central','https://fdc.nal.usda.gov/download-datasets/']];
function settingField(id,fa,en,min,max,step=1){return `<label class="field">${t(fa,en)}<input id="s-${id}" type="number" value="${state.settings[id]}" min="${min}" max="${max}" step="${step}" required></label>`}
function settingChoices(key,label,options){return `<fieldset class="setting-choices"><legend>${label}</legend><div class="grid2">${options.map(([value,symbol,label])=>`<button type="button" class="setting-choice" data-action="setting-choice" data-key="${key}" data-value="${value}" aria-pressed="${state.settings[key]===value}"><span class="choice-symbol" aria-hidden="true">${symbol}</span><span>${label}</span><span class="choice-check" aria-hidden="true">${state.settings[key]===value?'✓':'○'}</span></button>`).join('')}</div></fieldset>`}
function settingsPage(){let status=window.Android?JSON.parse(Android.notificationStatus()):null;return `${header(t('تنظیمات','Settings'))}<section class="card"><h2>${t('ظاهر، زبان و تاریخ','Appearance, language & calendar')}</h2>${settingChoices('theme',t('تم برنامه','App theme'),[['light','☀️',t('روشن','Light')],['dark','🌙',t('ذغالی و آبی','Charcoal & blue')]])}${settingChoices('lang',t('زبان','Language'),[['fa','🇮🇷','فارسی'],['en','🇬🇧','English']])}${settingChoices('calendar',t('تقویم','Calendar'),[['persian','▦',t('هجری شمسی','Solar Hijri')],['gregory','▦',t('میلادی','Gregorian')]])}</section><form id="settings-form"><section class="card"><h2>${t('هدف‌های روزانه','Daily goals')}</h2><p class="hint" style="margin-bottom:14px">${t('این اعداد نقطهٔ شروع عمومی هستند، نه نسخهٔ شخصی. کالری ۲۰۰۰ مرجع عمومی برچسب غذایی است؛ برای نیاز شخصی، هدف مناسب خودت یا متخصص را وارد کن.','These are starting references, not a personalized prescription. 2,000 kcal is a food-label reference; enter your own or your clinician’s target.')}</p>${settingField('weight','وزن (کیلوگرم)','Weight (kg)',30,300,.1)}<button type="button" class="secondary" data-action="protein-calc">${t('محاسبهٔ مرجع پروتئین: ۰٫۸ × وزن','Protein DRI reference: 0.8 × weight')}</button><p class="fine muted" style="margin:8px 0">${t('مرجع پایهٔ DRI برای بزرگسال سالم؛ نیاز ورزشکاران، سالمندان یا شرایط خاص ممکن است متفاوت باشد.','Baseline adult DRI; needs may differ with age, training or health conditions.')}</p><div class="grid2">${settingField('kcal','کالری (kcal)','Calories (kcal)',800,6000)}${settingField('protein','پروتئین (گرم)','Protein (g)',20,300)}${settingField('fiber','فیبر (گرم)','Fiber (g)',10,60)}${settingField('water','آب ساده (میلی‌لیتر)','Plain water (ml)',200,5000,100)}${settingField('activity','فعالیت متوسط (دقیقه)','Moderate activity (min)',1,300)}${settingField('breakLimit','حد نشستن پیوسته (دقیقه)','Sitting interval goal (min)',15,120,5)}</div><p class="fine muted">${t('فیبر: NIDDK بازهٔ ۲۲ تا ۳۴ گرم را با توجه به سن و جنس بیان می‌کند؛ افزایش تدریجی باشد. آب ۱۶۰۰ میلی‌لیتر و حد نشستن ۶۰ دقیقه انتخاب اولیهٔ برنامه‌اند، نه نیاز پزشکی همگانی. سایر نوشیدنی‌ها جدا گزارش می‌شوند. ۲۲ دقیقه فعالیت متوسط، تقسیم تقریبی حداقل ۱۵۰ دقیقه در هفتهٔ WHO است.','NIDDK describes 22–34 g fiber depending on age and sex; increase gradually. 1,600 ml plain water and 60-minute sitting stretches are app defaults, not universal medical requirements. Other drinks are tracked separately. 22 minutes of moderate activity approximates WHO’s 150-minute weekly minimum.')}</p><label class="check"><input type="checkbox" id="confirm-goals" ${state.settings.confirmed?'checked':''} required>${t('هدف‌ها را بررسی کرده‌ام؛ برای من مناسب‌اند.','I have reviewed these goals and they suit me.')}</label><p class="fine muted">${t('تغییر هدف‌ها فقط برای روزهایی است که هنوز ثبت نشده‌اند.','Changes apply to days not yet recorded.')}</p></section><section class="card"><h2>🔔 ${t('یادآوری‌ها','Reminders')}</h2><label class="check"><input id="s-reminders" type="checkbox" ${state.settings.reminders?'checked':''}>${t('فعال‌کردن اعلان‌ها','Enable reminders')}</label><p class="fine">${t('ثبت اطلاعات: ۹، ۱۲، ۱۵ و ۱۸. ساعت ۲۲: جمع‌بندی روز و پیشنهاد فردا. حرکت و آب: هر دو ساعت در بازهٔ بیداری.','Check-ins: 09:00, 12:00, 15:00 and 18:00. At 22:00: a daily review and suggestions for tomorrow. Movement and water: every 2 hours during waking hours.')}</p><div class="grid2">${settingField('wake','شروع بیداری (ساعت)','Wake hour',0,22)}${settingField('sleep','پایان بیداری (ساعت)','End hour',1,23)}</div><p class="hint">${status?(status.notifications?t('مجوز اعلان فعال است.','Notifications allowed.'):t('مجوز اعلان هنوز فعال نیست.','Notification permission is not enabled.')):t('اعلان‌ها در نسخهٔ نصب‌شدهٔ اندروید کار می‌کنند.','Reminders work in the installed Android app.')} ${t('بدون مجوز هشدار دقیق، اندروید ممکن است اعلان را با تأخیر نشان دهد.','Without exact-alarm access, Android may delay reminders.')}</p>${window.Android?`<button type="button" class="link" data-action="permissions">${t('مجوز اعلان و زمان‌بندی دقیق','Notification & exact-alarm access')}</button><button type="button" class="link" data-action="test-notification">${t('آزمایش اعلان','Test notification')}</button><button type="button" class="link" data-action="night-preview">${t('آزمایش جمع‌بندی شبانه','Test nightly review')}</button>`:''}</section><button type="submit" class="primary">${t('ذخیره و تأیید تنظیمات','Save & confirm settings')}</button></form><section class="card" style="margin-top:20px"><h2>${t('اطلاعات من','My data')}</h2><p class="fine">${t('اطلاعات روی همین گوشی ذخیره می‌شود. حساب کاربری و ارسال به سرور وجود ندارد. پیش از حذف برنامه یا تعویض گوشی، پشتیبان بگیر.','Data stays on this phone. No account or server upload. Back up before uninstalling or changing phones.')}</p><div class="actions"><button class="secondary" data-action="backup">${t('ذخیره پشتیبان','Export backup')}</button><button class="secondary" data-action="import">${t('بازیابی پشتیبان','Restore backup')}</button></div></section><section class="card"><h2>${t('منابع و توضیحات','Sources & notes')}</h2><p class="fine">${t('بررسی منابع: ۲۲ اکتبر ۲۰۲۶. بانک خوراکی‌ها: USDA SR Legacy آوریل ۲۰۱۸، دریافت یک‌باره. سیب سلامت برای پیگیری روزانهٔ تغذیه، آب و فعالیت طراحی شده است. مقادیر غذایی تقریبی‌اند و هدف‌ها قابل تنظیم هستند.','Sources reviewed October 22, 2026. Food database: USDA SR Legacy April 2018, downloaded once. Green Apple tracks daily nutrition, water and activity. Nutrition values are approximate and goals are adjustable.')}</p>${SOURCES.map(([label,url])=>`<button class="link" style="display:block;text-align:start" data-action="source" data-url="${url}">${label} ↗</button>`).join('')}<p class="fine muted">${t('سیب سلامت','Green Apple')} 1.4.0 · Android 11+ · Vazirmatn / SIL OFL<br>Cartoon icons: Twemoji © Twitter / jdecked contributors · CC BY 4.0</p></section>`}
function saveSettings(e){e.preventDefault();const old=JSON.stringify(state);for(const k of ['weight','kcal','protein','fiber','water','activity','breakLimit','wake','sleep'])state.settings[k]=Number($('#s-'+k).value);if(state.settings.wake>=state.settings.sleep){state=JSON.parse(old);toast(t('ساعت پایان باید پس از شروع باشد.','End hour must be after wake hour.'));return}state.settings.confirmed=$('#confirm-goals').checked;state.settings.reminders=$('#s-reminders').checked;if(!save()){state=JSON.parse(old);return}for(const key of Object.keys(state.ui.forms))if(key.startsWith('settings:'))delete state.ui.forms[key];save();if(window.Android)Android.configure(JSON.stringify(state.settings));toast(t('تنظیمات ذخیره شد','Settings saved'));page='home';render()}
function customModal(){modal(t('خوراکی یا غذای خانگی','Custom food or recipe'),`<form id="custom-form"><label class="field">${t('نام فارسی','Persian name')}<input id="c-fa" maxlength="100" required></label><label class="field">${t('نام انگلیسی (اختیاری)','English name (optional)')}<input id="c-en" maxlength="100"></label><label class="field">${t('دسته‌بندی','Category')}<select id="c-cat">${CATEGORIES.map(c=>`<option value="${c.id}" ${cat===c.id?'selected':''}>${name(c)}</option>`).join('')}</select></label><label class="check"><input id="c-drink" type="checkbox">${t('نوشیدنی است (واحد میلی‌لیتر)','Drink (milliliters)')}</label><p class="hint">${t('ارزش غذایی را از برچسب یا دستور محاسبه‌شده برای هر ۱۰۰ گرم / میلی‌لیتر وارد کن. اگر نمی‌دانی خالی بگذار؛ نامشخص با صفر فرق دارد.','Enter label or recipe nutrition per 100 g / ml. Leave unknown values empty; unknown is different from zero.')}</p><div class="grid2">${[['kcal','کالری','Calories'],['protein','پروتئین (گرم)','Protein (g)'],['fiber','فیبر (گرم)','Fiber (g)']].map(([k,fa,en])=>`<label class="field">${t(fa,en)}<input id="c-${k}" type="number" min="0" max="1000" step="any"></label>`).join('')}<label class="field">${t('مقدار پایه (گرم)','Base portion (g)')}<input id="c-base" type="number" value="100" min="1" max="2000" required></label></div><button class="primary" type="submit">${t('ذخیره خوراکی','Save food')}</button></form>`)}
function reportModal(){modal(t('گزارش PDF','PDF report'),`<p class="muted">${t('بازهٔ دلخواه را انتخاب کن؛ حداکثر ۳۱ روز در هر گزارش.','Choose up to 31 days per report.')}</p><label class="field">${t('از تاریخ','From')}<button class="secondary" style="width:100%" data-action="report-from">${df(reportStart)}</button></label><label class="field">${t('تا تاریخ','To')}<button class="secondary" style="width:100%" data-action="report-to">${df(reportEnd)}</button></label><button class="primary" data-action="print-report">${t('ساخت گزارش و ذخیره PDF','Create report & save PDF')}</button><p class="fine muted" style="margin-top:12px">${t('در پنجرهٔ چاپ اندروید، «Save as PDF» را انتخاب کن.','In Android’s print dialog, select “Save as PDF”.')}</p>`)}
function reportHTML(start,end){let dates=[];for(let k=start;k<=end;k=Core.shift(k,1))dates.push(k);return `<html lang="${state.settings.lang}" dir="${state.settings.lang==='fa'?'rtl':'ltr'}"><head><meta charset="utf-8"><link rel="stylesheet" href="style.css"><title>${t('گزارش سیب سلامت','Green Apple report')}</title></head><body><main>${dates.map(key=>{let d=state.days[key],v=Core.totals(d),s=Core.score(d);return `<section class="report-page"><h1>${t('سیب سلامت','Green Apple')} · ${t('گزارش روزانه','Daily report')}</h1><h2>${df(key)}</h2><p class="muted">${key} · ${d?.complete?t('روز کامل','Complete day'):t('اطلاعات ناقص / ثبت نشده','Incomplete / not recorded')}</p>${!d?.entries.length?`<p>${t('اطلاعاتی ثبت نشده است.','No data recorded.')}</p>`:`<table class="report-table"><thead><tr><th>${t('شاخص','Metric')}</th><th>${t('مصرف / مقدار','Recorded')}</th><th>${t('هدف','Target')}</th></tr></thead><tbody>${[['kcal',t('کالری','Calories'),'kcal'],['protein',t('پروتئین','Protein'),'g'],['fiber',t('فیبر','Fiber'),'g'],['water',t('آب ساده','Plain water'),'ml'],['fluids',t('همه نوشیدنی‌ها','All drinks'),'ml'],['activity',t('فعالیت','Activity'),'min'],['kegel',t('کگل','Kegel'),t('نوبت','sessions')],['sitting',t('نشستن','Sitting'),'min'],['longest',t('طولانی‌ترین نشستن','Longest sitting'),'min'],['breaks',t('وقفه‌ها','Breaks'),'']].map(([k,l,u])=>`<tr><td>${l}</td><td>${k==='sitting'||k==='longest'?duration(v[k]):n(v[k],1)+' '+u}</td><td>${k==='kegel'?n(3):d.targets[k]?n(d.targets[k]):'—'}</td></tr>`).join('')}</tbody></table><p>${t('امتیاز عادت‌ها','Habit score')}: ${s?n(s.value)+'%':'—'} ${v.unknown?t(' · ارزش غذایی نامشخص؛ جمع‌ها ناقص‌اند.',' · Unknown nutrition; totals incomplete.'):''}</p><table class="report-table"><thead><tr><th>${t('زمان','Time')}</th><th>${t('خوراکی / فعالیت','Food / activity')}</th><th>${t('مقدار','Amount')}</th></tr></thead><tbody>${d.entries.map(e=>e.items.map(i=>`<tr><td>${esc(intervalLabel(e))}</td><td>${esc(name(i.food))}</td><td>${n(i.amount)} ${i.food.drink?'ml':'g'}</td></tr>`).join('')+`<tr><td>${esc(intervalLabel(e))}</td><td>${t('نشستن / فعالیت / طولانی‌ترین نوبت / وقفه‌ها','Sitting / activity / longest stretch / breaks')}</td><td>${e.sitting===null?'—':duration(e.sitting)} / ${e.activity===null?'—':n(e.activity)+' '+t('دقیقه','min')} / ${e.sitting===null?'—':duration(e.sitting)} / ${e.breaks===null?'—':n(e.breaks)}</td></tr>`+(e.noFood||e.noDrink?`<tr><td>${esc(intervalLabel(e))}</td><td colspan="2">${e.noFood?t('بدون غذا در این نوبت','No food this interval'):''} ${e.noDrink?t('بدون نوشیدنی در این نوبت','No drinks this interval'):''}</td></tr>`:'')).join('')}</tbody></table>`}<p class="fine muted" style="margin-top:18px">${t('مقادیر غذایی تقریبی‌اند. این گزارش تشخیص پزشکی نیست. داده‌های پایه: USDA SR Legacy (۲۰۱۸). هدف‌ها توسط کاربر تأیید شده‌اند.','Nutrition is approximate. This is not a medical assessment. Base data: USDA SR Legacy (2018). Targets are user-confirmed.')}</p></section>`}).join('')}</main></body></html>`}
function printReport(){const span=(Date.parse(reportEnd+'T00:00:00Z')-Date.parse(reportStart+'T00:00:00Z'))/86400000;if(span<0||span>30||reportEnd>today()){toast(t('بازه باید ۱ تا ۳۱ روز و تا امروز باشد.','Choose 1–31 days ending no later than today.'));return}let html=reportHTML(reportStart,reportEnd);if(window.Android){Android.printReport(html);closeModal()}else{let w=window.open('','_blank');if(w){w.document.write(html);w.document.close();w.onload=()=>w.print()}else toast(t('پنجرهٔ چاپ مسدود شده است.','Print popup was blocked.'))}}
function openCalendar(callback,key){calendarCallback=callback;calendarAnchor=key;modal(t('انتخاب تاریخ','Choose date'),`<div id="calendar-container">${calGrid()}</div>`)}
function refreshCalendar(){if($('#calendar-container'))$('#calendar-container').innerHTML=calGrid()}
function jumpMonth(){const keep=calendarCallback;let p=calParts(calendarAnchor);modal(t('انتخاب ماه و سال','Choose month & year'),`<form id="jump-form"><label class="field">${t('سال','Year')}<input id="j-year" type="number" min="${state.settings.calendar==='persian'?1300:1921}" max="${state.settings.calendar==='persian'?1500:2121}" value="${p.year}" required></label><label class="field">${t('ماه (۱ تا ۱۲)','Month (1–12)')}<input id="j-month" type="number" min="1" max="12" value="${p.month}" required></label><button class="primary" type="submit">${t('نمایش','Show')}</button></form>`);window.jumpCallback=keep}
function doJump(e){e.preventDefault();let y=Number($('#j-year').value),m=Number($('#j-month').value),start=`${state.settings.calendar==='persian'?y+621:y}-01-01`,found=null;for(let i=0;i<740;i++){let k=Core.shift(start,i),p=calParts(k);if(p.year===y&&p.month===m&&p.day===1){found=k;break}}if(!found){toast(t('تاریخ معتبر نیست.','Invalid date.'));return}calendarAnchor=found;if(window.jumpCallback)openCalendar(window.jumpCallback,found);else{closeModal();page='history';render()}}
function backup(){const content=JSON.stringify(state,null,2);if(window.Android)Android.exportBackup(content);else{let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type:'application/json'}));a.download='sabz-backup-'+today()+'.json';a.click();URL.revokeObjectURL(a.href)}}
window.receiveBackup=raw=>{try{const imported=Core.validate(JSON.parse(raw));if(!confirm(t('اطلاعات فعلی با این پشتیبان جایگزین شود؟ ابتدا از اطلاعات فعلی پشتیبان داشته باش.','Replace current data with this backup? Make sure your current data is backed up.')))return;const old=state;state=imported;initUI();if(!save()){state=old;return}draft=null;editId=null;if(window.Android)Android.configure(JSON.stringify(state.settings));page='home';render();toast(t('پشتیبان بازیابی شد','Backup restored'))}catch(e){toast(t('فایل پشتیبان معتبر نیست؛ اطلاعات فعلی حفظ شد.','Invalid backup; current data was preserved.'))}};
window.onNativeError=()=>toast(t('عملیات انجام نشد. دوباره تلاش کن.','The operation failed. Please try again.'));
const ACTIVITIES=[{id:'walk',fa:'پیاده‌روی',en:'Walking',symbol:'walk'}, {id:'exercise',fa:'ورزش متوسط',en:'Moderate exercise',symbol:'exercise'}, {id:'stretch',fa:'کشش و حرکت سبک',en:'Stretch & move',symbol:'stretch'}, {id:'other',fa:'سایر فعالیت‌ها',en:'Other activity',symbol:'other'}];
function initUI(){state.settings.theme=state.settings.theme||'light';state.ui=state.ui||{sessions:{},forms:{}};state.ui.sessions=state.ui.sessions||{};state.ui.forms=state.ui.forms||{}}
function duration(value){const v=Math.round(value||0),h=Math.floor(v/60),m=v%60;return h?(n(h)+' '+t('ساعت','h')+(m?' '+t('و','')+' '+n(m)+' '+t('دقیقه','min'):'')):n(m)+' '+t('دقیقه','min')}
function amountText(f,v){return f.drink?n(v/200,1)+' '+t('لیوان','glasses'):n(v,1)+' '+t('گرم','g')}
function activityArt(kind){const paths={kegel:'M5 9c0 17 20 17 20 0M15 23V9m-5 5 5-5 5 5',walk:'M14 5a2 2 0 1 0 .1 0M12 10l-3 7-4 2m7-9 4 4 4 1M11 15l5 6 1 6M10 19l-3 8',exercise:'M5 9v14M2 12v8M23 9v14M26 12v8M5 16h18',stretch:'M14 4a2 2 0 1 0 .1 0M14 9v9M14 10 5 6M14 10l9-4M14 18 7 27M14 18l8 9',other:'M15 2 5 17h8l-1 11L24 12h-9Z'};return `<svg class="activity-art" viewBox="0 0 30 32" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[kind]}"/></svg>`}
let editingSession=null,lastClockDate=today();
function intervalLabel(e){return e.autoSlot===undefined?e.time:String(e.autoStart).padStart(2,'0')+':00 – '+String(e.autoSlot+3).padStart(2,'0')+':00'}
function ensureSession(){initUI();const now=new Date(),nowDate=Core.dayKey(now);if(!editingSession&&date===lastClockDate&&nowDate!==lastClockDate)date=nowDate;lastClockDate=nowDate;const entries=getDay().entries;let e=editingSession?.date===date?entries.find(x=>x.id===editingSession.id):null;let cached=state.ui.sessions[date];if(!e){const interval=Core.autoInterval(entries,date===nowDate?now.getHours():21);e=interval.entry;const id=e?.id||'auto-'+date+'-'+interval.slot;if(cached?.id!==id){cached={id,time:String(interval.slot).padStart(2,'0')+':00',hours:String(Math.floor((e?.sitting??60)/60)),minutes:String((e?.sitting??60)%60)};state.ui.sessions[date]=cached}draft=e?JSON.parse(JSON.stringify(e)):{...newDraft(),id,time:cached.time,autoSlot:interval.slot,autoStart:interval.start}}else{if(cached?.id!==e.id){cached={id:e.id,time:e.time,hours:String(Math.floor((e.sitting??60)/60)),minutes:String((e.sitting??60)%60)};state.ui.sessions[date]=cached}draft=JSON.parse(JSON.stringify(e))}if(!draft.activities){draft.activities={};if(draft.activity!==null)draft.activities[draft.activityType||'walk']=draft.activity}editId=draft.id;return draft}
function frequentSection(){const foods=Core.frequentFoods(state.days,allFoods());return `<section class="card frequent-foods"><h2>⭐ ${t('پرکاربردهای من','My frequent foods')}</h2><p class="fine muted">${t('بر اساس دفعات ثبت شما؛ مقدارها مربوط به نوبت جاری‌اند.','Based on your log frequency; amounts are for this interval.')}</p>${foods.map(f=>`<div class="instant-food"><button class="food-info" data-action="food-info" data-id="${esc(f.id)}"><span class="emoji">${esc(f.emoji)}</span><strong>${esc(name(f))}</strong></button>${foodControls(f,draft.items.filter(i=>i.food.id===f.id).reduce((sum,i)=>sum+i.amount,0))}</div>`).join('')||`<p class="muted">${t('با ثبت خوراکی‌ها، موارد پرکاربردت اینجا نمایش داده می‌شوند.','Your frequent foods will appear here as you log them.')}</p>`}</section>`}

function transactSession(change){if(loadError)return false;if(!state.settings.confirmed){toast(t('ابتدا هدف‌های روزانه را در تنظیمات تأیید کن.','Confirm your daily goals in Settings first.'));return false}if(date>today()){toast(t('برای روز آینده نمی‌توان ثبت کرد.','Future dates cannot be logged.'));return false}ensureSession();const before=JSON.stringify(state),entry=JSON.parse(JSON.stringify(draft));if(!getDay().entries.some(e=>e.id===entry.id)&&entry.sitting===null)entry.sitting=60;change(entry);entry.longest=entry.sitting;entry.activity=Object.keys(entry.activities||{}).length?Object.values(entry.activities).reduce((a,b)=>a+b,0):entry.activity;const d=ensureDay(),idx=d.entries.findIndex(e=>e.id===entry.id);if(idx<0)d.entries.push(entry);else d.entries[idx]=entry;d.entries=d.entries.filter(e=>e.autoSlot===undefined||Core.hasEntryData(e));d.complete=false;const sum=Core.totals(d);if(sum.sitting>1440||sum.activity>1440){state=JSON.parse(before);ensureSession();toast(t('مجموع زمان یک روز نمی‌تواند بیش از ۲۴ ساعت باشد.','A daily duration cannot exceed 24 hours.'));return false}if(!save()){state=JSON.parse(before);ensureSession();return false}draft=entry;return true}
function refreshInPlace(){const y=window.scrollY;render();window.scrollTo(0,y)}
function changeFood(id,dir,exact){ensureSession();const f=allFoods().find(f=>f.id===id)||draft.items.find(i=>i.food.id===id)?.food;if(!f)return;const current=draft.items.filter(i=>i.food.id===id).reduce((v,i)=>v+i.amount,0);const next=exact!==undefined?exact:Core.nextFoodAmount(f,current,dir);if(!Number.isFinite(next)||next<0||next>20000){toast(t('مقدار معتبر وارد کن.','Enter a valid amount.'));return}if(transactSession(e=>{e.items=e.items.filter(i=>i.food.id!==id);if(next>0)e.items.push({food:{...f},amount:next});if(f.drink)e.noDrink=next===0&&!e.items.some(i=>i.food.drink);else e.noFood=next===0&&!e.items.some(i=>!i.food.drink)})){refreshInPlace();if($('#modal').innerHTML&&quantityFood?.id===id)foodInfo(id)}}
function foodControls(f,amount){return `<div class="inline-amount" data-food="${esc(f.id)}"><div class="inline-stepper" dir="ltr"><button data-action="food-minus" data-id="${esc(f.id)}" aria-label="${t('کم کردن','Decrease')} ${esc(name(f))}" ${amount===0?'disabled':''}>−</button><span class="amount" aria-live="polite">${amountText(f,amount)}</span><button data-action="food-plus" data-id="${esc(f.id)}" aria-label="${t('زیاد کردن','Increase')} ${esc(name(f))}">+</button></div></div>`}
function header(title){return `<header class="top"><div><div class="brand">${t('سیب سلامت','Green Apple')} · ${t('همراه روزهای سالم','A little healthier, daily')}</div><h1>${title}</h1></div><div class="row header-actions"><button class="iconbtn" data-action="theme" aria-label="${state.settings.theme==='dark'?t('تم روشن','Light theme'):t('تم تیره','Dark theme')}" aria-pressed="${state.settings.theme==='dark'}">${state.settings.theme==='dark'?'☀':'☾'}</button><button class="iconbtn" data-action="settings" aria-label="${t('تنظیمات','Settings')}">${icon('settings')}</button></div></header>`}
function mascot(score){const happy=score===null||score>=65;return `<svg class="mascot apple" viewBox="0 0 170 190" role="img" aria-label="${happy?t('سیب سبز خندان','Smiling green apple'):t('سیب سبز خسته','Tired green apple')}"><ellipse cx="85" cy="178" rx="49" ry="6" fill="#487659" opacity=".15"/><path d="M84 58Q79 37 89 24" fill="none" stroke="#775139" stroke-width="7" stroke-linecap="round"/><path d="M88 43C95 17 123 16 132 22C127 43 107 51 88 43Z" fill="#388347"/><path d="M85 61C55 40 23 56 21 89C17 123 37 168 61 172C73 175 78 168 85 168C93 168 99 175 111 172C136 168 154 123 149 89C145 55 116 40 85 61Z" fill="${happy?'#84c83f':'#91b663'}"/><path d="M85 61C116 40 145 55 149 89C154 123 136 168 111 172C99 175 93 168 85 168C112 150 127 92 112 56Z" fill="#559e37" opacity=".4"/><path d="M37 89Q39 72 53 68" fill="none" stroke="#e1f4ba" stroke-width="8" stroke-linecap="round"/>${happy?'<path d="M55 111Q61 103 67 111M103 111Q109 103 115 111" fill="none" stroke="#294b2b" stroke-width="4" stroke-linecap="round"/>':'<path d="M55 111l12 2M103 113l12-2" fill="none" stroke="#294b2b" stroke-width="4" stroke-linecap="round"/>'}<ellipse cx="50" cy="123" rx="9" ry="5" fill="#f1b195" opacity=".7"/><ellipse cx="120" cy="123" rx="9" ry="5" fill="#f1b195" opacity=".7"/><path d="${happy?'M70 130Q85 151 100 130Z':'M73 140Q85 130 97 140'}" fill="${happy?'#294b2b':'none'}" stroke="#294b2b" stroke-width="3" stroke-linecap="round"/>${happy?'<path d="M77 138Q85 145 93 138" fill="#f3a49b"/>':''}</svg>`}

function waterCard(v,g){const ratio=Math.min(100,v/g*100);return `<section class="card water-card"><div class="row between"><div><h3>${t('آب سادهٔ امروز','Plain water today')}</h3><b>${n(v/200,1)} ${t('لیوان از','of')} ${n(g/200,1)}</b><p class="muted">${n(v)} / ${n(g)} ${t('میلی‌لیتر','ml')}</p></div><div class="water-ring" role="progressbar" aria-valuemin="0" aria-valuemax="${g}" aria-valuenow="${Math.min(v,g)}" aria-label="${t('پیشرفت آب روزانه','Daily water progress')}"><svg viewBox="0 0 100 100"><circle class="ring-bg" cx="50" cy="50" r="40"/><circle class="ring-fill" cx="50" cy="50" r="40" pathLength="100" stroke-dasharray="${ratio} 100"/></svg><span>${n(v/g*100)}٪</span></div></div><button class="secondary" data-action="water">＋ ${t('یک لیوان آب · ثبت فوری','One glass · log now')}</button></section>`}
function kegelCard(total){const count=draft.kegel||0;return `<div class="activity-tile ${count>0?'chosen':''}"><button class="activity-choice" data-action="kegel-select" aria-pressed="${count>0}">${activityArt('kegel')}<strong>${t('کگل','Kegel')}</strong><small>${t('هدف روزانه: حداقل ۳ نوبت','Daily goal: at least 3 sessions')}</small></button><div class="inline-stepper" dir="ltr"><button data-action="kegel-minus" aria-label="${t('کاهش نوبت کگل','Fewer Kegel sessions')}" ${count===0?'disabled':''}>−</button><span>${n(count)} ${t('نوبت','sessions')}</span><button data-action="kegel-plus" aria-label="${t('افزایش نوبت کگل','More Kegel sessions')}">+</button></div><p class="fine">${t('امروز','Today')}: ${n(total)} / ${n(3)} ${t('نوبت','sessions')} ${total>=3?'✓':''}</p></div>`}
function quick(){ensureSession();const session=state.ui.sessions[date],v=Core.totals(getDay());const sit=draft.sitting;return `${header(t('ثبت سریع','Quick log'))}<div class="row between">${dateChip()}</div><div class="autosave-note">✓ ${t('هر تغییر همان لحظه ثبت می‌شود','Every change is saved immediately')} · <bdi dir="ltr">${esc(intervalLabel(draft))}</bdi></div>${editingSession?`<button class="link" data-action="end-edit">${t('پایان ویرایش؛ بازگشت به ثبت خودکار','Finish editing; return to automatic logging')}</button>`:''}${frequentSection()}<section class="card"><div class="row between"><h2>🥗 ${t('خوراکی و نوشیدنی','Food & drinks')}</h2><button class="secondary" data-action="foods">${t('دسته‌بندی‌ها','Categories')} ←</button></div>${draft.items.map(i=>`<div class="instant-food"><button class="food-info" data-action="food-info" data-id="${esc(i.food.id)}"><span class="emoji">${esc(i.food.emoji)}</span><strong>${esc(name(i.food))}</strong><span class="info-mark">ⓘ</span></button>${foodControls(i.food,i.amount)}</div>`).join('')||`<p class="muted">${t('خوراکی‌ها را از دسته‌بندی انتخاب کن.','Choose foods from the categories.')}</p>`}<label class="check"><input type="checkbox" data-none="noFood" ${draft.noFood?'checked':''} ${draft.items.some(i=>!i.food.drink)?'disabled':''}>${t('در این نوبت چیزی نخوردم','No food this interval')}</label><label class="check"><input type="checkbox" data-none="noDrink" ${draft.noDrink?'checked':''} ${draft.items.some(i=>i.food.drink)?'disabled':''}>${t('در این نوبت چیزی ننوشیدم','No drinks this interval')}</label></section><section class="card"><h2>🪑 ${t('نشستن این نوبت','Sitting this interval')}</h2><div class="stepper"><button data-action="sit-minus" aria-label="${t('۱۵ دقیقه کمتر نشستن','15 fewer sitting minutes')}">−</button><button class="duration-display" data-action="sit-default">${duration(sit===null?60:sit)}<small>${sit===null?t('پیش‌فرض؛ با اولین ثبت ذخیره می‌شود','Default · saved with your first log'):t('ثبت شده','Recorded')}</small></button><button data-action="sit-plus" aria-label="${t('۱۵ دقیقه بیشتر نشستن','15 more sitting minutes')}">+</button></div><div class="grid2 time-inputs"><label class="field">${t('ساعت','Hours')}<input id="sit-hours" type="number" min="0" max="24" step="1" inputmode="numeric" value="${esc(session.hours)}"></label><label class="field">${t('دقیقه','Minutes')}<input id="sit-minutes" type="number" min="0" max="59" step="1" inputmode="numeric" value="${esc(session.minutes)}"></label></div><p id="sit-validation" class="fine">${validSittingInput()?t('هر گام: ۱۵ دقیقه','Each step: 15 minutes'):t('ورودی نیمه‌تمام حفظ شده؛ ساعت و دقیقه را کامل کن.','Draft retained. Complete the hours and minutes.')}</p><div class="hint" style="margin-top:12px">${t('مجموع روز','Day total')}: <strong id="sit-day-total">${duration(v.sitting)}</strong><br>${t('طولانی‌ترین نوبت','Longest interval')}: <strong id="sit-day-longest">${duration(v.longest)}</strong></div><p class="fine muted" style="margin-top:10px">${t('نوبت‌ها خودکار سه‌ساعته‌اند. با اولین ثبت، ۱ ساعت نشستن منظور می‌شود؛ مقدار واقعی را می‌توانی تغییر دهی. بازه‌های خالی ادغام می‌شوند.','Intervals advance every 3 hours. Your first log includes 1 hour of sitting; adjust it to your actual time. Empty periods merge into the next interval.')}</p><button class="link" data-action="zero-sit">${t('این نوبت ننشستم','No sitting this interval')}</button><div class="row between"><span>${t('وقفه‌های بلندشدن','Standing breaks')}</span><div class="inline-stepper" dir="ltr"><button data-action="break-minus" aria-label="${t('کاهش وقفه','Fewer breaks')}">−</button><span>${draft.breaks===null?'—':n(draft.breaks)}</span><button data-action="break-plus" aria-label="${t('افزایش وقفه','More breaks')}">+</button></div></div></section><section class="card"><h2>${t('فعالیت‌های این نوبت','Activity this interval')}</h2><p class="muted" style="margin-bottom:14px">${t('انتخاب هر فعالیت زمانی، ۲۰ دقیقه ثبت می‌کند؛ گام تغییر ۱۰ دقیقه است.','Select a timed activity to log 20 minutes; adjust in 10-minute steps.')}</p><div class="grid2 activities">${ACTIVITIES.map(a=>{const minutes=draft.activities[a.id],selected=minutes!==undefined;return `<div class="activity-tile ${selected?'chosen':''}"><button class="activity-choice" data-action="activity-select" data-kind="${a.id}" aria-pressed="${selected}">${activityArt(a.symbol)}<strong>${name(a)}</strong><small>${selected?n(minutes)+' '+t('دقیقه','min'):t('شروع با ۲۰ دقیقه','Start with 20 min')}</small></button>${selected?`<div class="inline-stepper" dir="ltr"><button data-action="activity-minus" data-kind="${a.id}" aria-label="${t('کاهش','Decrease')} ${name(a)}" ${minutes===0?'disabled':''}>−</button><span>${n(minutes)} ${t('دقیقه','min')}</span><button data-action="activity-plus" data-kind="${a.id}" aria-label="${t('افزایش','Increase')} ${name(a)}">+</button></div>`:''}</div>`}).join('')}${kegelCard(v.kegel)}</div><p class="hint" style="margin-top:14px">${t('مجموع فعالیت روز','Daily activity')}: ${n(v.activity)} ${t('دقیقه','min')}</p><button class="link" data-action="zero-active">${t('این نوبت فعالیت نداشتم','No activity this interval')}</button></section><button class="secondary" style="width:100%" data-action="back-home">${t('برگشت به خانه','Back home')}</button><p class="fine muted" style="margin-top:12px">${t('با خروج چیزی پاک نمی‌شود؛ نوبت جاری برای برگشت بعدی حفظ می‌شود.','Leaving does not discard anything; your current interval is retained.')}</p>`}
function foodsPage(){ensureSession();const list=allFoods().filter(f=>(!cat||f.cat===cat)&&(!search||[f.fa,f.en].some(s=>s.toLowerCase().includes(search.toLowerCase()))));return `${header(cat?name(CATEGORIES.find(c=>c.id===cat)):t('چی خوردی؟','What did you have?'))}<div class="row between"><button class="link" data-action="food-back">→ ${cat||search?t('دسته‌بندی‌ها','Categories'):t('ثبت سریع','Quick log')}</button><span class="chip">${df(date)}</span></div><input id="search" type="search" value="${esc(search)}" placeholder="${t('جستجوی خوراکی…','Search foods…')}" style="margin:12px 0 16px"><p class="autosave-note">✓ ${t('مقدار این نوبت؛ تغییرها فوری ثبت می‌شوند','This interval’s amounts · saved immediately')}</p>${!cat&&!search?`${frequentSection()}<div class="grid2">${CATEGORIES.map(c=>`<button class="tile" data-action="category" data-id="${c.id}"><span class="emoji">${c.emoji}</span><strong>${name(c)}</strong><small>${n(allFoods().filter(f=>f.cat===c.id).length)} ${t('خوراکی','items')}</small></button>`).join('')}</div>`:`<section class="card food-list">${list.map(f=>{const amount=draft.items.filter(i=>i.food.id===f.id).reduce((v,i)=>v+i.amount,0);return `<div class="instant-food"><button class="food-info" data-action="food-info" data-id="${esc(f.id)}"><span class="emoji">${esc(f.emoji)}</span><strong>${esc(name(f))}</strong><span class="info-mark">ⓘ</span></button>${foodControls(f,amount)}</div>`}).join('')||`<p class="muted">${t('موردی پیدا نشد؛ خوراکی خودت را اضافه کن.','No matching foods. Add your own.')}</p>`}</section>`}<button class="secondary" style="width:100%;margin-top:18px" data-action="custom">＋ ${t('خوراکی یا غذای خانگی جدید','New food or home recipe')}</button><p class="fine muted" style="margin-top:12px">${t('اولین + سهم پایه را ثبت می‌کند؛ بعدی‌ها ۲۰٪ سهم پایه. نوشیدنی: هر گام یک لیوان ۲۰۰ میلی‌لیتری.','First + logs the base portion, then steps are 20% of that portion. Drinks: one 200 ml glass per step.')}</p>`}
function foodInfo(id){ensureSession();quantityFood=allFoods().find(f=>f.id===id)||draft.items.find(i=>i.food.id===id)?.food;const f=quantityFood;if(!f)return;const amount=draft.items.filter(i=>i.food.id===id).reduce((v,i)=>v+i.amount,0);modal(name(f),`<span class="big-emoji">${esc(f.emoji)}</span>${foodControls(f,amount)}<label class="field" style="margin-top:14px">${t('مقدار دقیق','Exact amount')} (${f.drink?t('میلی‌لیتر','ml'):t('گرم','g')})<input id="food-exact" type="number" min="0" max="20000" step="any" value="${esc(state.ui.forms['food:'+date+':'+draft.id+':'+f.id]??amount)}"></label><p class="hint">${f.kcal===null||f.protein===null||f.fiber===null?t('بخشی از ارزش غذایی نامشخص است؛ جمع روز ناقص خواهد بود.','Some nutrition is unknown; daily totals will be incomplete.'):t(`هر ۱۰۰ ${f.drink?'میلی‌لیتر':'گرم'}: ${n(f.kcal)} کالری، ${n(f.protein,1)} گرم پروتئین و ${n(f.fiber,1)} گرم فیبر.`,`Per 100 ${f.drink?'ml':'g'}: ${f.kcal} kcal, ${f.protein} g protein, ${f.fiber} g fiber.`)}${f.approx?'<br>'+t('تبدیل حجم به وزن تقریبی است.','Volume-to-weight conversion is approximate.'):''}</p><details style="margin-top:15px"><summary>${t('منبع داده','Data source')}</summary><p class="fine" dir="ltr">${esc(f.source||'User-provided label / recipe')}${f.fdcId?' · FDC '+f.fdcId:''}</p></details>`)}
function validSittingInput(){const s=state.ui.sessions[date];return s&&s.hours!==''&&s.minutes!==''&&Number.isInteger(Number(s.hours))&&Number.isInteger(Number(s.minutes))&&Number(s.hours)>=0&&Number(s.hours)<=24&&Number(s.minutes)>=0&&Number(s.minutes)<60&&Number(s.hours)*60+Number(s.minutes)<=1440}
function setSitting(minutes,refresh=true){if(!Number.isInteger(minutes)||minutes<0||minutes>1440)return false;if(transactSession(e=>{e.sitting=minutes;e.longest=minutes})){const s=state.ui.sessions[date];s.hours=String(Math.floor(minutes/60));s.minutes=String(minutes%60);save();if(refresh)refreshInPlace();return true}return false}
function sessionBack(){if(page==='foods'){if(cat||search){cat=null;search='';render()}else navigate('quick')}else navigate('home')}
function navigate(p){if(!['quick','foods'].includes(p))editingSession=null;page=p;draft=null;editId=null;if(p==='quick'||p==='foods')ensureSession();if(p==='history')calendarAnchor=date;render()}
function syncDraftInputs(){const key=page==='settings'?'settings':$('#custom-form')?'custom':null;if(!key)return;document.querySelectorAll(key==='settings'?'#settings-form input':'#custom-form input,#custom-form select').forEach(el=>{const cached=state.ui.forms[key+':'+el.id];if(cached!==undefined){if(el.type==='checkbox')el.checked=cached;else el.value=cached}})}
function applyTheme(){document.documentElement.dataset.theme=state.settings.theme||'light';document.querySelector('meta[name="theme-color"]').content=state.settings.theme==='dark'?'#181A20':'#087f78';if(window.Android&&typeof Android.setTheme==='function')Android.setTheme(state.settings.theme==='dark')}
function render(){initUI();document.documentElement.lang=state.settings.lang;document.documentElement.dir=state.settings.lang==='fa'?'rtl':'ltr';applyTheme();const views={home:dashboard,quick,foods:foodsPage,details,history,trend,settings:settingsPage};$('#app').innerHTML=`<main class="shell">${(views[page]||dashboard)()}</main>${nav()}`;upgradeArt();syncDraftInputs();window.scrollTo(0,0)}

window.openReview=key=>{if(Core.validDate(key)){date=key;navigate('details')}};
window.openQuick=()=>{date=today();navigate('quick')};
window.nativeBack=()=>{if($('#modal').innerHTML){closeModal();return}if(page==='home'){if(window.Android)Android.minimize();return}sessionBack()};
document.addEventListener('input',e=>{const el=e.target;
 if(el.id==='search'){const pos=el.selectionStart;search=el.value;const y=window.scrollY;render();$('#search').focus();$('#search').setSelectionRange?.(pos,pos);window.scrollTo(0,y);return}
 if(el.id==='sit-hours'||el.id==='sit-minutes'){ensureSession();state.ui.sessions[date][el.id==='sit-hours'?'hours':'minutes']=el.value;save();if(validSittingInput()){const s=state.ui.sessions[date],minutes=Number(s.hours)*60+Number(s.minutes);if(setSitting(minutes,false)){const sum=Core.totals(getDay());$('.duration-display').innerHTML=duration(minutes)+`<small>${t('ثبت شده','Recorded')}</small>`;$('#sit-day-total').textContent=duration(sum.sitting);$('#sit-day-longest').textContent=duration(sum.longest);$('#sit-validation').textContent=t('✓ ثبت شد · هر گام ۱۵ دقیقه','✓ Recorded · 15-minute steps')}}else $('#sit-validation').textContent=t('ورودی نیمه‌تمام حفظ شد؛ ساعت ۰ تا ۲۴ و دقیقه ۰ تا ۵۹.','Draft retained; hours 0–24 and minutes 0–59.');return}
 if(el.id==='food-exact'){const key='food:'+date+':'+draft.id+':'+quantityFood.id;state.ui.forms[key]=el.value;save();if(el.value!==''&&Number.isFinite(Number(el.value))&&Number(el.value)>=0&&Number(el.value)<=20000){const f=quantityFood,amount=Number(el.value);transactSession(entry=>{entry.items=entry.items.filter(i=>i.food.id!==f.id);if(amount>0)entry.items.push({food:{...f},amount});if(f.drink)entry.noDrink=amount===0&&!entry.items.some(i=>i.food.drink);else entry.noFood=amount===0&&!entry.items.some(i=>!i.food.drink)});document.querySelectorAll('[data-food="'+CSS.escape(f.id)+'"] .amount').forEach(x=>x.textContent=amountText(f,amount))}return}
 if(el.closest('#settings-form')||el.closest('#custom-form')){const prefix=el.closest('#custom-form')?'custom:':'settings:';state.ui.forms[prefix+el.id]=el.type==='checkbox'?el.checked:el.value;save()}
});
document.addEventListener('change',e=>{const el=e.target;
 if(el.dataset.none){if(transactSession(entry=>{entry[el.dataset.none]=el.checked}))refreshInPlace();else el.checked=!el.checked;return}
 if(el.closest('#custom-form')||el.closest('#settings-form')){const prefix=el.closest('#custom-form')?'custom:':'settings:';state.ui.forms[prefix+el.id]=el.type==='checkbox'?el.checked:el.value;save()}
});
document.addEventListener('submit',e=>{if(e.target.id==='settings-form')saveSettings(e);if(e.target.id==='jump-form')doJump(e);if(e.target.id==='custom-form'){e.preventDefault();const c=CATEGORIES.find(c=>c.id===$('#c-cat').value),drink=$('#c-drink').checked;const f={id:'custom-'+uid(),fa:$('#c-fa').value.trim(),en:$('#c-en').value.trim()||$('#c-fa').value.trim(),cat:c.id,emoji:c.emoji,base:drink?200:Number($('#c-base').value),drink,water:false,source:'User-provided label / recipe',approx:false};for(const k of ['kcal','protein','fiber'])f[k]=$('#c-'+k).value===''?null:Number($('#c-'+k).value);if(!f.fa){toast(t('نام را وارد کن.','Enter a name.'));return}state.custom.push(f);if(save()){for(const key of Object.keys(state.ui.forms))if(key.startsWith('custom:'))delete state.ui.forms[key];save();closeModal();page='foods';cat=c.id;search='';render();toast(t('خوراکی اضافه شد؛ مقدارش را با + ثبت کن.','Food added. Use + to log an amount.'))}else state.custom.pop()}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;
 if(a==='close'){closeModal();if(page==='foods'||page==='quick')refreshInPlace()}
 if(a==='setting-choice'){const key=b.dataset.key,value=b.dataset.value;if(!({theme:['light','dark'],lang:['fa','en'],calendar:['persian','gregory']}[key]||[]).includes(value))return;const previous=state.settings[key];state.settings[key]=value;if(!save()){state.settings[key]=previous;return}if(window.Android)Android.configure(JSON.stringify(state.settings));render()}
 if(a==='theme'){state.settings.theme=state.settings.theme==='dark'?'light':'dark';save();refreshInPlace()}
 if(a==='nav')navigate(b.dataset.page);
 if(a==='settings')navigate('settings');
 if(a==='today'){date=today();calendarAnchor=date;navigate('home')}
 if(a==='date')openCalendar(k=>{date=k;navigate('details')},date);
 if(a==='details')navigate('details');
 if(a==='foods'){cat=null;search='';navigate('foods')}
 if(a==='food-back')sessionBack();
 if(a==='back-home')navigate('home');
 if(a==='category'){cat=b.dataset.id;search='';render()}
 if(a==='food-info')foodInfo(b.dataset.id);
 if(a==='food-plus'||a==='food-minus'){ensureSession();delete state.ui.forms['food:'+date+':'+draft.id+':'+b.dataset.id];changeFood(b.dataset.id,a==='food-plus'?1:-1)}
 if(a==='water'){changeFood('173647',1)}
 if(a==='sit-plus'||a==='sit-minus'){ensureSession();const base=draft.sitting===null?60:draft.sitting;setSitting(Math.max(0,Math.min(1440,base+(a==='sit-plus'?15:-15))))}
 if(a==='sit-default'){ensureSession();setSitting(draft.sitting===null?60:draft.sitting)}
 if(a==='zero-sit')setSitting(0);
 if(a==='break-plus'||a==='break-minus'){if(transactSession(entry=>{entry.breaks=Math.max(0,Math.min(1440,(entry.breaks||0)+(a==='break-plus'?1:-1)))}))refreshInPlace()}
 if(a==='activity-select'||a==='activity-plus'||a==='activity-minus'){const kind=b.dataset.kind;if(!ACTIVITIES.some(x=>x.id===kind))return;ensureSession();const old=draft.activities[kind];if(a==='activity-select'&&old!==undefined)return;const next=old===undefined?20:Math.max(0,old+(a==='activity-plus'?10:-10));if(transactSession(entry=>{entry.activities[kind]=next;entry.activity=Object.values(entry.activities).reduce((x,y)=>x+y,0)}))refreshInPlace()}
 if(a==='kegel-select'||a==='kegel-plus'||a==='kegel-minus'){ensureSession();if(a==='kegel-select'&&(draft.kegel||0)>0)return;if(transactSession(entry=>{entry.kegel=Math.min(1000,Math.max(0,(entry.kegel||0)+(a==='kegel-minus'?-1:1)))}))refreshInPlace()}
 if(a==='zero-active'){if(transactSession(entry=>{entry.activities={walk:0,exercise:0,stretch:0,other:0};entry.activity=0;entry.kegel=0}))refreshInPlace()}
 if(a==='edit-entry'){editingSession={date,id:b.dataset.id};navigate('quick')}
 if(a==='end-edit'){editingSession=null;navigate('quick')}

 if(a==='delete-entry'){if(confirm(t('این نوبت حذف شود؟','Delete this interval?'))){const old=JSON.stringify(state);const day=ensureDay();day.entries=day.entries.filter(x=>x.id!==b.dataset.id);day.complete=false;if(state.ui.sessions[date]?.id===b.dataset.id)delete state.ui.sessions[date];if(save())render();else state=JSON.parse(old)}}
 if(a==='complete'){const d=getDay();if(d.complete){state.days[date].complete=false;save();render();return}if(!Object.values(Core.coverage(d)).every(Boolean)){toast(t('ابتدا غذا، نوشیدنی، نشستن و فعالیت را ثبت کن؛ صفر هم قابل ثبت است.','Record food, drinks, sitting and activity; explicit zero is allowed.'));return}if(confirm(t('همهٔ مصرف و فعالیت این روز ثبت شده است؟','Have you recorded the whole day?'))){ensureDay().complete=true;if(save())render();else ensureDay().complete=false}}
 if(a==='month-prev'||a==='month-next'){const start=monthStart(calendarAnchor);calendarAnchor=a==='month-prev'?Core.shift(start,-1):Core.shift(start,32);refreshCalendar()}
 if(a==='jump-month')jumpMonth();
 if(a==='select-date'){const k=b.dataset.date;if(calendarCallback){const cb=calendarCallback;closeModal();cb(k)}else{date=k;navigate('details')}}
 if(a==='open-day'){date=b.dataset.date;navigate('details')}
 if(a==='custom'){customModal();syncDraftInputs()}
 if(a==='protein-calc'){$('#s-protein').value=Math.round(Number($('#s-weight').value)*.8);state.ui.forms['settings:s-protein']=$('#s-protein').value;save()}
 if(a==='permissions'&&window.Android)Android.requestPermissions();
 if(a==='test-notification'&&window.Android)Android.testNotification();
 if(a==='night-preview'){if(window.Android&&typeof Android.testNightReview==='function')Android.testNightReview();else toast(t('پیش‌نمایش اعلان در نسخهٔ نصب‌شدهٔ اندروید در دسترس است.','Notification preview is available in the installed Android app.'))}
 if(a==='report'){reportStart=Core.shift(date,-6);reportEnd=date;reportModal()}
 if(a==='report-from')openCalendar(k=>{reportStart=k;reportModal()},reportStart);
 if(a==='report-to')openCalendar(k=>{reportEnd=k;reportModal()},reportEnd);
 if(a==='print-report')printReport();
 if(a==='backup')backup();
 if(a==='import'){if(window.Android)Android.importBackup();else{const input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=async()=>{if(input.files[0]?.size>5000000){toast(t('فایل بیش از حد بزرگ است.','File too large.'));return}if(input.files[0])window.receiveBackup(await input.files[0].text())};input.click()}}
 if(a==='source'){if(window.Android)Android.openSource(b.dataset.url);else window.open(b.dataset.url,'_blank','noopener')}
});
initUI();render();if(loadError){modal(t('خطا در خواندن اطلاعات','Data could not be loaded'),`<p>${t('اطلاعات قبلی قابل خواندن نیست. برای جلوگیری از بازنویسی، ثبت غیرفعال شد. از پشتیبان معتبر بازیابی کن.','Existing data could not be read. Saving is disabled to protect it. Restore a valid backup.')}</p>`);save=()=>false}

function refreshAutoInterval(){if(editingSession||!['home','quick','foods'].includes(page)||document.activeElement?.matches('input,select,textarea'))return;const old=date+':'+(draft?.id||'');ensureSession();if(old!==date+':'+draft.id){closeModal();refreshInPlace()}}
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshAutoInterval()});
window.addEventListener('focus',refreshAutoInterval);
setInterval(refreshAutoInterval,30000);
